// Short English renderings of meaning; linked references provide the complete hadith.
const dailyHadiths=[
{theme:'Begin with intention',text:'Deeds are judged by intentions, and each person receives according to what they intended.',narrator:'Umar ibn al-Khattab',reference:'Sahih al-Bukhari 1',url:'https://sunnah.com/bukhari:1'},
{theme:'Choose good words',text:'Whoever believes in Allah and the Last Day should speak good or remain silent.',narrator:'Abu Huraira',reference:'Sahih al-Bukhari 6018',url:'https://sunnah.com/bukhari:6018'},
{theme:'Wish good for others',text:'None of you truly believes until he loves for his brother what he loves for himself.',narrator:'Anas ibn Malik',reference:'Sahih al-Bukhari 13',url:'https://sunnah.com/bukhari:13'},
{theme:'Strength in patience',text:'True strength is controlling yourself when angry, rather than overpowering others.',narrator:'Abu Huraira',reference:'Sahih al-Bukhari 6114',url:'https://sunnah.com/bukhari:6114'},
{theme:'Small, steady deeds',text:'The deeds most beloved to Allah are those done consistently, even when small.',narrator:'Aisha',reference:'Sahih al-Bukhari 6464',url:'https://sunnah.com/bukhari:6464'},
{theme:'Give, forgive, be humble',text:'Charity does not diminish wealth. Allah increases the honor of those who forgive and raises those who are humble for His sake.',narrator:'Abu Huraira',reference:'Sahih Muslim 2588',url:'https://sunnah.com/muslim:2588'},
{theme:'Live with sincerity',text:'Religion is sincerity: toward Allah, His Book, His Messenger, the Muslim leaders, and the Muslim community.',narrator:'Tamim ad-Dari',reference:'Sahih Muslim 55a',url:'https://sunnah.com/muslim:55a'}
];
function hadithForDate(date,zone){const parts=new Intl.DateTimeFormat('en-US',{timeZone:zone,year:'numeric',month:'numeric',day:'numeric'}).formatToParts(date),get=k=>Number(parts.find(p=>p.type===k).value);const day=Math.floor(Date.UTC(get('year'),get('month')-1,get('day'))/86400000);return dailyHadiths[((day%dailyHadiths.length)+dailyHadiths.length)%dailyHadiths.length]}
function renderDailyHadith(){const zone=typeof data!=='undefined'&&data?.meta?.timezone?data.meta.timezone:Intl.DateTimeFormat().resolvedOptions().timeZone;const h=hadithForDate(new Date(),zone);document.getElementById('hadith-theme').textContent=h.theme;document.getElementById('hadith-text').textContent=h.text;document.getElementById('hadith-narrator').textContent='Narrated by '+h.narrator;const source=document.getElementById('hadith-source');source.textContent=h.reference+' ↗';source.href=h.url;document.getElementById('hadith-date').textContent=new Intl.DateTimeFormat('en-US',{timeZone:zone,month:'long',day:'numeric'}).format(new Date())}
renderDailyHadith();setInterval(renderDailyHadith,30000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)renderDailyHadith()});
